files.patch:
@@ -142,1 +142,0 @@
-    // Adjust address to point to narrow oop
@@ -144,1 +143,5 @@
-    __ lea($tmp1$$Register, dst.plus_disp(4));
+    // Adjust address to point to narrow oop if we need any barrier. Otherwise, no need to touch tmp1 at all.
+    // We don't save any instruction, but we make the generated assembly less confusing for the poor soul who
+    // will step through that during debugging.
+    int off = ((barrier_data() & G1C2BarrierPre) == 0 && (barrier_data() & G1C2BarrierPost) == 0) ? 0 : 4;
+    __ lea($tmp1$$Register, dst.plus_disp(off));
@@ -152,1 +155,1 @@
-    __ movq(Address($tmp1$$Register, -4), $src$$Register);
+    __ movq(Address($tmp1$$Register, -off), $src$$Register);
@@ -180,8 +183,11 @@
-    write_barrier_pre(masm, this,
-                      $tmp1$$Register /* obj */,
-                      $tmp2$$Register /* pre_val */,
-                      $tmp3$$Register /* tmp */,
-                      RegSet::of($tmp1$$Register, $src$$Register) /* preserve */);
-    if ((barrier_data() & G1C2BarrierPre) != 0 || (barrier_data() & G1C2BarrierPost) != 0) {
-      // Adjust address to point to the second narrow oop in the long value, but only if we need to generate
-      // a barrier
+    if ((barrier_data() & G1C2BarrierPre) == 0 && (barrier_data() & G1C2BarrierPost) == 0) {
+      // In case we need barriers, we need tmp1 to walk over both oops, either for pre- or post- barrier.
+      // But if we don't need any, we can save all these shenanigans and keep it simple.
+      __ movq(Address($tmp1$$Register, 0), $src$$Register);
+    } else {
+      write_barrier_pre(masm, this,
+                        $tmp1$$Register /* obj */,
+                        $tmp2$$Register /* pre_val */,
+                        $tmp3$$Register /* tmp */,
+                        RegSet::of($tmp1$$Register, $src$$Register) /* preserve */);
+      // Adjust address to point to the second narrow oop in the long value.
@@ -189,6 +195,5 @@
-    }
-    write_barrier_pre(masm, this,
-                      $tmp1$$Register /* obj */,
-                      $tmp2$$Register /* pre_val */,
-                      $tmp3$$Register /* tmp */,
-                      RegSet::of($tmp1$$Register, $src$$Register) /* preserve */);
+      write_barrier_pre(masm, this,
+                        $tmp1$$Register /* obj */,
+                        $tmp2$$Register /* pre_val */,
+                        $tmp3$$Register /* tmp */,
+                        RegSet::of($tmp1$$Register, $src$$Register) /* preserve */);
@@ -196,1 +201,0 @@
-    if ((barrier_data() & G1C2BarrierPre) != 0 || (barrier_data() & G1C2BarrierPost) != 0) {
@@ -199,4 +203,0 @@
-    } else {
-      // If no barrier is needed, we didn't adjust tmp1, so we don't need to adjust it here again.
-      __ movq(Address($tmp1$$Register, 0), $src$$Register);
-    }
@@ -204,8 +204,9 @@
-    // Do the post-barrier of the second oop first since we have its address in tmp1
-    if ((barrier_data() & G1C2BarrierPost) != 0) {
-      __ movq($tmp2$$Register, $src$$Register);
-      __ shrq($tmp2$$Register, 32);
-      if ((barrier_data() & G1C2BarrierPostNotNull) == 0) {
-        __ decode_heap_oop($tmp2$$Register);
-      } else {
-        __ decode_heap_oop_not_null($tmp2$$Register);
+      // Do the post-barrier of the second oop first since we have its address in tmp1
+      if ((barrier_data() & G1C2BarrierPost) != 0) {
+        __ movq($tmp2$$Register, $src$$Register);
+        __ shrq($tmp2$$Register, 32);
+        if ((barrier_data() & G1C2BarrierPostNotNull) == 0) {
+          __ decode_heap_oop($tmp2$$Register);
+        } else {
+          __ decode_heap_oop_not_null($tmp2$$Register);
+        }
@@ -213,15 +214,15 @@
-    }
-    write_barrier_post(masm, this,
-                       $tmp1$$Register /* store_addr */,
-                       $tmp2$$Register /* new_val */,
-                       $tmp3$$Register /* tmp1 */);
-
-    // Retrieve the address of the first narrow oop
-    __ addq($tmp1$$Register, -4);
-    // Extract the first narrow oop
-    if ((barrier_data() & G1C2BarrierPost) != 0) {
-      __ movl($tmp2$$Register, $src$$Register);
-      if ((barrier_data() & G1C2BarrierPostNotNull) == 0) {
-        __ decode_heap_oop($tmp2$$Register);
-      } else {
-        __ decode_heap_oop_not_null($tmp2$$Register);
+      write_barrier_post(masm, this,
+                         $tmp1$$Register /* store_addr */,
+                         $tmp2$$Register /* new_val */,
+                         $tmp3$$Register /* tmp1 */);
+
+      // Extract the first narrow oop
+      if ((barrier_data() & G1C2BarrierPost) != 0) {
+        // Retrieve the address of the first narrow oop
+        __ addq($tmp1$$Register, -4);
+        __ movl($tmp2$$Register, $src$$Register);
+        if ((barrier_data() & G1C2BarrierPostNotNull) == 0) {
+          __ decode_heap_oop($tmp2$$Register);
+        } else {
+          __ decode_heap_oop_not_null($tmp2$$Register);
+        }
@@ -229,5 +230,5 @@
-    }
-    write_barrier_post(masm, this,
-                       $tmp1$$Register /* store_addr */,
-                       $tmp2$$Register /* new_val */,
-                       $tmp3$$Register /* tmp1 */);
+      write_barrier_post(masm, this,
+                         $tmp1$$Register /* store_addr */,
+                         $tmp2$$Register /* new_val */,
+                         $tmp3$$Register /* tmp1 */);
+     }
